public static class DesktopProtocolValidation
{
    public static bool TryValidate(InitializeParams value, out string errorCode)
    {
        if (value is null)
        {
            errorCode = DesktopProtocolDefinition.InvalidParamsError;
            return false;
        }

        if (!(value.SchemaVersion >= 1 && value.SchemaVersion <= 1))
        {
            errorCode = DesktopProtocolDefinition.InvalidParamsError;
            return false;
        }

        if (!(value.ProtocolVersion is not null && Encoding.UTF8.GetByteCount(value.ProtocolVersion) <= 32 && value.ProtocolVersion is ("desktop-v1")))
        {
            errorCode = DesktopProtocolDefinition.InvalidParamsError;
            return false;
        }

        if (!(value.ContractSha256 is not null && Encoding.UTF8.GetByteCount(value.ContractSha256) <= 64))
        {
            errorCode = DesktopProtocolDefinition.InvalidParamsError;
            return false;
        }

        if (!(value.ClientName is not null && Encoding.UTF8.GetByteCount(value.ClientName) <= 128))
        {
            errorCode = DesktopProtocolDefinition.InvalidParamsError;
            return false;
        }

        if (!(value.ClientVersion is not null && Encoding.UTF8.GetByteCount(value.ClientVersion) <= 128))
        {
            errorCode = DesktopProtocolDefinition.InvalidParamsError;
            return false;
        }

        if (!(value.ClientInstanceId is not null && Encoding.UTF8.GetByteCount(value.ClientInstanceId) <= 128))
        {
            errorCode = DesktopProtocolDefinition.InvalidParamsError;
